    public static final int VERSION_OFFSET = 4;
    public static final int FLAGS_OFFSET = 8;
    public static final int CIPHER_OFFSET = 9;
    public static final int NONCE_OFFSET = 10;
    public static final int MAC_OFFSET = 22;
    public static final int KEY_CHECK_OFFSET = 38;

    /** Where the body begins. The header before it is always this long. */
